# -*- coding: utf-8 -*-
# Studi Kasus Koding JavaScript (bahasa "js"): dijalankan di Web Worker; jawaban diharapkan dihitung Node (alat/uji-js.js).
# Tes = ekspresi JS; tes multi-baris harus mengisi variabel `hasil`. Nilai dibandingkan setelah JSON.

def J(id, judul, tingkat, fungsi, soal, solusi, tes, petunjuk, jelas, cek=None, awal=None, cerita="", pre=""):
    return dict(id=id, judul=judul, tingkat=tingkat, bahasa="js", fungsi=fungsi, soal=soal, solusi=solusi, tes=tes,
                petunjuk=petunjuk, jelas=jelas, cek=cek or {}, cerita=cerita, pre=pre,
                awal=awal or f"function {fungsi}() {{\n  // tulis kodemu di sini\n}}\n")

def ujian_js(id, setelah, judul, cakupan, cerita, bagian):
    langkah, lalu = [], ""
    for n, b in enumerate(bagian):
        sol = lalu + b["solusi"]
        L_ = J(f"{id}-{'abc'[n]}", f"Bagian {'ABC'[n]}: {b['judul']}", min(3, n + 2), b["fungsi"], b["soal"], sol, b["tes"], b["petunjuk"], b["jelas"],
               cek=b.get("cek"), awal=lalu + b["awal"],
               cerita=cerita if n == 0 else f"Lanjutan bagian {'AB'[n - 1]}. Kodemu yang sudah lulus ada di editor; tambahkan fungsi baru di bawahnya.")
        if n:
            L_["awal_baru"] = b["awal"]
        if "contoh" in b:
            L_["contoh"] = b["contoh"]
        langkah.append(L_)
        lalu = sol + "\n"
    studi(id=id, topik="js", setelah=setelah, judul=judul, ujian=True, cakupan=cakupan, bahasa="js",
          contoh=dict(PANDUAN, kode='const bersihkan = t => t.trim().toLowerCase();\nconst hitung = daftar => daftar.reduce((o, k) => ({ ...o, [k]: (o[k] || 0) + 1 }), {});\nconst laporan = mentah => Object.entries(hitung(mentah.map(bersihkan))).sort();\nconsole.log(laporan([" Kopi", "teh ", "KOPI"]));'),
          langkah=langkah)

# ---------------------------------------------------------------- 1. dasar
studi(id="js-dasar", topik="js", setelah="dasar", judul="Variabel, tipe, dan template literal", bahasa="js",
  contoh=dict(judul="Contoh: const, let, template literal",
    penjelasan="<p><code>const</code> untuk nilai yang tidak diganti, <code>let</code> untuk yang berubah. Template literal (diapit backtick) menyisipkan nilai dengan <code>${...}</code>. <code>typeof</code> memberi tahu tipe data.</p>",
    kode='const nama = "Jauza";\nlet umur = 22;\numur = umur + 1;\nconsole.log(`Halo, ${nama}! Umur ${umur} tahun.`);\nconsole.log(typeof nama, typeof umur, typeof true);\nconsole.log((19.99 * 3).toFixed(2));',
    kunci="Pakai const secara bawaan, let hanya bila nilainya memang berubah. Jangan pakai var."),
  langkah=[
    J("js-dasar-1", "Luas dan keliling", 1, "persegiPanjang",
      "Buat <code>persegiPanjang(p, l)</code> yang mengembalikan objek <code>{ luas, keliling }</code>.",
      'function persegiPanjang(p, l) {\n  const luas = p * l;\n  const keliling = 2 * (p + l);\n  return { luas, keliling };\n}\n',
      ["persegiPanjang(4, 3)", "persegiPanjang(0, 5)", "persegiPanjang(2.5, 2)", "persegiPanjang(10, 10)"],
      ["Hitung dua nilai dengan const, lalu return objek.", "Singkatan properti: { luas, keliling } sama dengan { luas: luas, keliling: keliling }."],
      "Mengembalikan objek memudahkan pemanggil mengambil beberapa hasil sekaligus.",
      cek={"persegiPanjang(4, 3)": {"luas": 12, "keliling": 14}}),
    J("js-dasar-2", "Kartu nama", 1, "kartuNama",
      "Buat <code>kartuNama(nama, posisi, kota)</code> yang mengembalikan teks <code>\"Jauza | Odoo Developer | Batam\"</code>. Nama dirapikan (<code>trim</code>) dan posisi ditulis huruf besar semua bila <code>posisi</code> berupa singkatan 2–3 huruf (misalnya \"qa\" → \"QA\").",
      'function kartuNama(nama, posisi, kota) {\n  const pos = posisi.length <= 3 ? posisi.toUpperCase() : posisi;\n  return `${nama.trim()} | ${pos} | ${kota}`;\n}\n',
      ['kartuNama("Jauza", "Odoo Developer", "Batam")', 'kartuNama("  Ani ", "qa", "Solo")', 'kartuNama("Budi", "UX", "Jakarta")', 'kartuNama("Cita", "data", "Medan")'],
      ["Template literal: `${a} | ${b} | ${c}`.", "Syarat singkatan: posisi.length <= 3, lalu toUpperCase()."],
      "Ekspresi kondisi ? a : b (ternary) cocok untuk memilih nilai dalam satu baris.",
      cek={'kartuNama("  Ani ", "qa", "Solo")': "Ani | QA | Solo"}),
  ])

# ---------------------------------------------------------------- 2. operator
studi(id="js-operator", topik="js", setelah="operator", judul="=== , ternary, dan ??", bahasa="js",
  contoh=dict(judul="Contoh: perbandingan ketat dan nilai bawaan",
    penjelasan="<p>Selalu pakai <code>===</code>: <code>\"5\" == 5</code> bernilai true karena tipe diubah diam-diam, sedangkan <code>\"5\" === 5</code> false. <code>??</code> memberi nilai bawaan hanya bila nilainya <code>null</code>/<code>undefined</code>, berbeda dengan <code>||</code> yang juga mengganti 0 dan string kosong.</p>",
    kode='console.log("5" == 5, "5" === 5);\nconst stok = 0;\nconsole.log(stok || 10, stok ?? 10);\nconst member = true;\nconsole.log(member ? "Diskon 10%" : "Harga normal");\nconsole.log(7 % 2 === 1 ? "ganjil" : "genap");',
    kunci="=== selalu. ?? untuk nilai bawaan yang menghormati 0. Ternary untuk pilihan dua nilai."),
  langkah=[
    J("js-op-1", "Ganjil atau genap", 1, "jenisAngka",
      "Buat <code>jenisAngka(n)</code> yang mengembalikan <code>\"genap\"</code> atau <code>\"ganjil\"</code>. Bila <code>n</code> bukan bilangan bulat (misalnya 2.5 atau \"4\"), kembalikan <code>\"bukan bilangan bulat\"</code>.",
      'function jenisAngka(n) {\n  if (!Number.isInteger(n)) return "bukan bilangan bulat";\n  return n % 2 === 0 ? "genap" : "ganjil";\n}\n',
      ["jenisAngka(4)", "jenisAngka(7)", "jenisAngka(-3)", "jenisAngka(0)", 'jenisAngka("4")', "jenisAngka(2.5)"],
      ["Number.isInteger(\"4\") bernilai false karena tipenya string.", "-3 % 2 bernilai -1, jadi cek genap dengan === 0, bukan ganjil dengan === 1."],
      "Di JavaScript, sisa bagi bilangan negatif ikut negatif. Mengecek === 0 untuk genap menghindari jebakan itu.",
      cek={"jenisAngka(-3)": "ganjil"}),
    J("js-op-2", "Harga dengan nilai bawaan", 2, "hargaAkhir",
      "Buat <code>hargaAkhir(produk)</code>. <code>produk</code> punya <code>harga</code> dan mungkin <code>diskon</code> (persen) serta <code>pajak</code> (persen). Diskon bawaan 0, pajak bawaan 11, tetapi <b>pajak 0 harus tetap 0</b>. Kembalikan harga setelah diskon lalu pajak, dibulatkan dengan <code>Math.round</code>.",
      'function hargaAkhir(produk) {\n  const diskon = produk.diskon ?? 0;\n  const pajak = produk.pajak ?? 11;\n  return Math.round(produk.harga * (1 - diskon / 100) * (1 + pajak / 100));\n}\n',
      ["hargaAkhir({ harga: 100000 })", "hargaAkhir({ harga: 100000, diskon: 10 })", "hargaAkhir({ harga: 100000, pajak: 0 })", "hargaAkhir({ harga: 50000, diskon: 0, pajak: 0 })", "hargaAkhir({ harga: 19999, diskon: 15 })"],
      ["Gunakan ?? untuk nilai bawaan.", "Dengan ||, pajak: 0 akan berubah menjadi 11; itulah jebakannya."],
      "?? hanya mengganti null/undefined. Bug '0 dianggap kosong' sering terjadi pada diskon, stok, atau qty.",
      cek={"hargaAkhir({ harga: 100000, pajak: 0 })": 100000}),
  ])

# ---------------------------------------------------------------- 3. kondisi & perulangan
studi(id="js-loop", topik="js", setelah="kondisiloop", judul="if, for, dan for...of", bahasa="js",
  contoh=dict(judul="Contoh: for klasik, for...of, break",
    penjelasan="<p><code>for (let i = 0; i &lt; n; i++)</code> bila butuh indeks, <code>for (const x of array)</code> untuk menelusuri isi, <code>break</code> untuk berhenti lebih awal.</p>",
    kode='const nilai = [70, 85, 40, 92];\nfor (const n of nilai) {\n  if (n < 50) {\n    console.log("Ada yang tidak lulus:", n);\n    break;\n  }\n}\nlet total = 0;\nfor (let i = 1; i <= 5; i++) total += i;\nconsole.log(total);',
    kunci="for...of untuk isi array, for...in untuk kunci objek (jarang dipakai untuk array)."),
  langkah=[
    J("js-loop-1", "FizzBuzz JavaScript", 1, "fizzbuzz",
      "Buat <code>fizzbuzz(n)</code> yang mengembalikan array untuk 1..n: kelipatan 3 → \"Fizz\", 5 → \"Buzz\", keduanya → \"FizzBuzz\", lainnya angka sebagai <b>number</b>.",
      'function fizzbuzz(n) {\n  const hasil = [];\n  for (let i = 1; i <= n; i++) {\n    if (i % 15 === 0) hasil.push("FizzBuzz");\n    else if (i % 3 === 0) hasil.push("Fizz");\n    else if (i % 5 === 0) hasil.push("Buzz");\n    else hasil.push(i);\n  }\n  return hasil;\n}\n',
      ["fizzbuzz(5)", "fizzbuzz(15)", "fizzbuzz(0)", "fizzbuzz(1)"],
      ["Cek kelipatan 15 lebih dulu.", "push(i) memasukkan angka (number), bukan string."],
      "Soal yang sama seperti Python, tetapi perhatikan tipe: di sini angka tetap number.",
      cek={"fizzbuzz(5)": [1, 2, "Fizz", 4, "Buzz"]}),
    J("js-loop-2", "Stok pertama yang habis", 2, "pertamaHabis",
      "Buat <code>pertamaHabis(stok, keluar)</code>: <code>stok</code> angka awal, <code>keluar</code> array jumlah barang keluar per hari. Kembalikan nomor hari (mulai 1) saat stok pertama kali ≤ 0, atau <code>-1</code> bila tidak pernah habis. Berhenti memeriksa setelah stok habis.",
      'function pertamaHabis(stok, keluar) {\n  for (let i = 0; i < keluar.length; i++) {\n    stok -= keluar[i];\n    if (stok <= 0) return i + 1;\n  }\n  return -1;\n}\n',
      ["pertamaHabis(10, [3, 4, 5, 1])", "pertamaHabis(10, [1, 1])", "pertamaHabis(5, [5])", "pertamaHabis(0, [])", "pertamaHabis(3, [0, 0, 4])"],
      ["Kurangi stok setiap hari, lalu cek.", "Indeks array mulai 0, nomor hari mulai 1: return i + 1."],
      "return di dalam for langsung menghentikan fungsi, sama seperti break lalu return.",
      cek={"pertamaHabis(10, [3, 4, 5, 1])": 3}),
  ])

# ---------------------------------------------------------------- 4. fungsi
studi(id="js-fungsi", topik="js", setelah="fungsi", judul="Arrow function dan fungsi tingkat tinggi", bahasa="js",
  contoh=dict(judul="Contoh: parameter bawaan dan fungsi yang mengembalikan fungsi",
    penjelasan="<p>Arrow function <code>(a, b) =&gt; a * b</code> ringkas untuk fungsi kecil. Parameter bawaan <code>(harga, pajak = 11)</code>. Fungsi bisa menerima atau mengembalikan fungsi lain (<i>higher-order function</i>).</p>",
    kode='const kali = (a, b) => a * b;\nconst denganPajak = (harga, pajak = 11) => harga * (1 + pajak / 100);\nconst pengali = n => x => x * n;\nconst gandakan = pengali(2);\nconsole.log(kali(3, 4), denganPajak(100), gandakan(21));',
    kunci="Arrow dengan satu ekspresi otomatis return. Bila memakai { }, return wajib ditulis."),
  langkah=[
    J("js-fun-1", "Konversi suhu", 1, "keFahrenheit",
      "Buat arrow function <code>keFahrenheit</code> dengan parameter <code>c</code> dan <code>desimal = 1</code> yang mengembalikan F = C × 9/5 + 32 dibulatkan ke <code>desimal</code> angka di belakang koma (hasil berupa number).",
      'const keFahrenheit = (c, desimal = 1) => Number((c * 9 / 5 + 32).toFixed(desimal));\n',
      ["keFahrenheit(100)", "keFahrenheit(36.6)", "keFahrenheit(-40)", "keFahrenheit(21.123, 2)"],
      ["toFixed menghasilkan string; bungkus dengan Number().", "Parameter bawaan: (c, desimal = 1) =>."],
      "toFixed mengembalikan string, sumber bug klasik saat hasilnya dijumlahkan lagi.",
      awal="const keFahrenheit = () => {\n  // tulis kodemu di sini\n};\n",
      cek={"keFahrenheit(36.6)": 97.9}),
    J("js-fun-2", "Pembuat diskon", 2, "buatDiskon",
      "Buat <code>buatDiskon(persen)</code> yang <b>mengembalikan fungsi</b>. Fungsi itu menerima harga dan mengembalikan harga setelah diskon (Math.round). Persen di luar 0–100 dibatasi ke rentang itu.",
      'function buatDiskon(persen) {\n  const p = Math.min(100, Math.max(0, persen));\n  return harga => Math.round(harga * (1 - p / 100));\n}\n',
      ["buatDiskon(10)(50000)", "buatDiskon(0)(1999)", "buatDiskon(150)(1000)", "buatDiskon(-5)(1000)", "[1000, 2500].map(buatDiskon(20))"],
      ["return harga => ... mengembalikan fungsi baru yang 'mengingat' persen.", "Batasi dengan Math.min(100, Math.max(0, persen))."],
      "Fungsi yang mengingat variabel dari luar disebut closure. Tes terakhir memakai fungsi hasil buatDiskon sebagai callback map.",
      cek={"[1000, 2500].map(buatDiskon(20))": [800, 2000]}),
  ])

# ---------------------------------------------------------------- 5. array
studi(id="js-array", topik="js", setelah="array", judul="map, filter, reduce, sort", bahasa="js",
  contoh=dict(judul="Contoh: rantai method array",
    penjelasan="<p><code>filter</code> menyaring, <code>map</code> mengubah setiap item, <code>reduce</code> meringkas menjadi satu nilai, <code>sort((a, b) =&gt; a - b)</code> mengurutkan angka. Semua kecuali sort tidak mengubah array asli.</p>",
    kode='const produk = [\n  { nama: "Kopi", harga: 18000, stok: 5 },\n  { nama: "Teh", harga: 6000, stok: 0 },\n  { nama: "Roti", harga: 15000, stok: 2 },\n];\nconst tersedia = produk.filter(p => p.stok > 0).map(p => p.nama);\nconst totalNilai = produk.reduce((t, p) => t + p.harga * p.stok, 0);\nconst termurah = [...produk].sort((a, b) => a.harga - b.harga).map(p => p.nama);\nconsole.log(tersedia, totalNilai, termurah);',
    kunci="sort mengubah array asli; salin dulu dengan [...arr]. sort tanpa fungsi mengurutkan sebagai teks."),
  langkah=[
    J("js-arr-1", "Daftar harga setelah diskon", 1, "daftarDiskon",
      "Buat <code>daftarDiskon(produk, persen)</code>: ambil produk dengan <code>stok &gt; 0</code>, lalu kembalikan array <code>{ nama, harga }</code> dengan harga setelah diskon (Math.round).",
      'function daftarDiskon(produk, persen) {\n  return produk\n    .filter(p => p.stok > 0)\n    .map(p => ({ nama: p.nama, harga: Math.round(p.harga * (1 - persen / 100)) }));\n}\n',
      ['daftarDiskon([{ nama: "Kopi", harga: 18000, stok: 5 }, { nama: "Teh", harga: 6000, stok: 0 }], 10)', "daftarDiskon([], 50)", 'daftarDiskon([{ nama: "A", harga: 999, stok: 1 }], 33)'],
      ["filter dulu, baru map.", "Mengembalikan objek dari arrow function perlu kurung: p => ({ ... })."],
      "Tanpa kurung, p => { nama: ... } dianggap blok kode, bukan objek, sehingga hasilnya undefined.",
      cek={'daftarDiskon([{ nama: "Kopi", harga: 18000, stok: 5 }, { nama: "Teh", harga: 6000, stok: 0 }], 10)': [{"nama": "Kopi", "harga": 16200}]}),
    J("js-arr-2", "Ringkasan per kategori", 2, "ringkasKategori",
      "Buat <code>ringkasKategori(produk)</code> yang memakai <code>reduce</code> untuk menghasilkan objek <code>{ kategori: totalNilaiStok }</code> (harga × stok), lalu kembalikan array <code>[kategori, total]</code> diurutkan dari total terbesar; seri diurutkan nama kategori. Array asli tidak boleh berubah.",
      'function ringkasKategori(produk) {\n  const total = produk.reduce((acc, p) => {\n    acc[p.kategori] = (acc[p.kategori] || 0) + p.harga * p.stok;\n    return acc;\n  }, {});\n  return Object.entries(total).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));\n}\n',
      ['ringkasKategori([{ kategori: "Minuman", harga: 18000, stok: 5 }, { kategori: "Makanan", harga: 15000, stok: 2 }, { kategori: "Minuman", harga: 6000, stok: 10 }])', "ringkasKategori([])", 'ringkasKategori([{ kategori: "B", harga: 1, stok: 1 }, { kategori: "A", harga: 1, stok: 1 }])',
       'const data = [{ kategori: "X", harga: 2, stok: 1 }, { kategori: "Y", harga: 5, stok: 1 }];\nringkasKategori(data);\nconst hasil = data.map(p => p.kategori);'],
      ["reduce dengan akumulator objek {}: acc[k] = (acc[k] || 0) + nilai; return acc.", "Object.entries(obj) → array [kunci, nilai]; urutkan dengan b[1] - a[1] || a[0].localeCompare(b[0])."],
      "|| di fungsi sort menjadi pemecah seri: bila selisih total 0, bandingkan nama.",
      cek={"ringkasKategori([])": []}),
  ])

# ---------------------------------------------------------------- 6. string & objek
studi(id="js-strobj", topik="js", setelah="strobj", judul="Destructuring dan spread", bahasa="js",
  contoh=dict(judul="Contoh: membongkar dan menyalin objek",
    penjelasan="<p>Destructuring mengambil properti ke variabel: <code>const { nama, alamat: { kota } } = user</code>. Spread <code>{ ...lama, ...baru }</code> menyalin dan menimpa tanpa mengubah objek asli.</p>",
    kode='const user = { nama: "Ani", email: "ani@x.id", alamat: { kota: "Batam" } };\nconst { nama, alamat: { kota } } = user;\nconsole.log(nama, kota);\nconst baru = { ...user, email: "ani@baru.id" };\nconsole.log(user.email, baru.email);\nconsole.log(Object.keys(user), "  odoo  ".trim().toUpperCase());',
    kunci="Spread menyalin satu tingkat (dangkal). Objek di dalamnya masih dipakai bersama."),
  langkah=[
    J("js-so-1", "Ringkas profil", 1, "ringkasProfil",
      "Buat <code>ringkasProfil(user)</code> memakai destructuring di parameter: kembalikan <code>\"Ani (ani@x.id) - Batam\"</code>. Bila <code>alamat</code> tidak ada, tulis kota <code>\"-\"</code>.",
      'function ringkasProfil({ nama, email, alamat = {} }) {\n  const { kota = "-" } = alamat;\n  return `${nama} (${email}) - ${kota}`;\n}\n',
      ['ringkasProfil({ nama: "Ani", email: "ani@x.id", alamat: { kota: "Batam" } })', 'ringkasProfil({ nama: "Budi", email: "b@y.id" })', 'ringkasProfil({ nama: "Cita", email: "c@z.id", alamat: {} })'],
      ["Destructuring di parameter: function f({ nama, email, alamat = {} }).", "Nilai bawaan saat destructuring: const { kota = \"-\" } = alamat."],
      "Nilai bawaan di destructuring mencegah error 'Cannot read properties of undefined'.",
      cek={'ringkasProfil({ nama: "Budi", email: "b@y.id" })': "Budi (b@y.id) - -"}),
    J("js-so-2", "Perbarui tanpa merusak", 2, "perbarui",
      "Buat <code>perbarui(profil, perubahan)</code> yang mengembalikan profil <b>baru</b>: properti dari <code>perubahan</code> menimpa yang lama, kecuali properti bernilai <code>undefined</code> diabaikan, dan <code>email</code> selalu disimpan huruf kecil tanpa spasi tepi. Profil asli tidak boleh berubah.",
      'function perbarui(profil, perubahan) {\n  const bersih = Object.fromEntries(Object.entries(perubahan).filter(([, v]) => v !== undefined));\n  const hasil = { ...profil, ...bersih };\n  if (hasil.email) hasil.email = hasil.email.trim().toLowerCase();\n  return hasil;\n}\n',
      ['perbarui({ nama: "Ani", email: "a@x.id" }, { email: " ANI@Baru.ID " })', 'perbarui({ nama: "Ani", kota: "Solo" }, { kota: undefined, umur: 22 })',
       'const lama = { nama: "Budi", email: "b@x.id" };\nperbarui(lama, { nama: "Budi S" });\nconst hasil = lama;', 'perbarui({}, {})'],
      ["Buang dulu nilai undefined: Object.entries(...).filter(([, v]) => v !== undefined), lalu Object.fromEntries.", "Gabungkan dengan spread { ...profil, ...bersih }, lalu rapikan email."],
      "Pola 'buat salinan baru, jangan ubah aslinya' (immutable update) adalah dasar state di React dan reducer.",
      cek={'perbarui({}, {})': {}}),
  ])

# ---------------------------------------------------------------- 7. dom (tanpa DOM: membangun HTML dengan aman)
studi(id="js-dom", topik="js", setelah="dom", judul="Membangun HTML dengan aman", bahasa="js",
  contoh=dict(judul="Contoh: data → HTML, dengan escape",
    penjelasan="<p>Sebelum menyisipkan teks dari pengguna ke <code>innerHTML</code>, karakter <code>&amp; &lt; &gt; \"</code> harus di-<i>escape</i>; tanpa itu, nama seperti <code>&lt;img onerror=...&gt;</code> bisa menjalankan skrip (XSS). Di DOM sungguhan, <code>textContent</code> otomatis aman.</p>",
    kode='const esc = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");\nconst produk = ["Kopi", "<b>Teh</b>"];\nconst html = "<ul>" + produk.map(p => `<li>${esc(p)}</li>`).join("") + "</ul>";\nconsole.log(html);\n// di halaman: document.querySelector("#daftar").innerHTML = html;',
    kunci="Data pengguna → escape → baru masuk innerHTML. Atau pakai textContent."),
  langkah=[
    J("js-dom-1", "Daftar HTML yang aman", 1, "daftarHTML",
      "Buat <code>daftarHTML(items)</code> yang mengembalikan string <code>&lt;ul&gt;&lt;li&gt;…&lt;/li&gt;…&lt;/ul&gt;</code>. Setiap item di-escape: <code>&amp;</code> → <code>&amp;amp;</code>, <code>&lt;</code> → <code>&amp;lt;</code>, <code>&gt;</code> → <code>&amp;gt;</code>. Array kosong → <code>&lt;ul&gt;&lt;/ul&gt;</code>.",
      'const esc = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");\n\nfunction daftarHTML(items) {\n  return "<ul>" + items.map(i => `<li>${esc(i)}</li>`).join("") + "</ul>";\n}\n',
      ['daftarHTML(["Kopi", "Teh"])', 'daftarHTML([])', 'daftarHTML(["<script>alert(1)</script>"])', 'daftarHTML(["A & B", 42])'],
      ["map tiap item menjadi `<li>…</li>`, lalu join(\"\").", "Ganti & PALING DULU, supaya &lt; hasil penggantian tidak ikut berubah menjadi &amp;lt;."],
      "Urutan replace penting: & harus diganti pertama. Ini cara kerja fungsi esc() yang dipakai KodeQuiz sendiri.",
      cek={'daftarHTML(["A & B", 42])': "<ul><li>A &amp; B</li><li>42</li></ul>"}),
    J("js-dom-2", "Tabel dari data", 2, "tabelHTML",
      "Buat <code>tabelHTML(baris)</code>: <code>baris</code> array objek dengan kunci yang sama. Kembalikan <code>&lt;table&gt;&lt;thead&gt;&lt;tr&gt;&lt;th&gt;kunci…&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;&lt;tr&gt;&lt;td&gt;nilai…&lt;/td&gt;&lt;/tr&gt;…&lt;/tbody&gt;&lt;/table&gt;</code> (semua nilai di-escape seperti soal 1). Array kosong → string kosong.",
      'const esc = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");\n\nfunction tabelHTML(baris) {\n  if (!baris.length) return "";\n  const kunci = Object.keys(baris[0]);\n  const kepala = "<tr>" + kunci.map(k => `<th>${esc(k)}</th>`).join("") + "</tr>";\n  const isi = baris.map(b => "<tr>" + kunci.map(k => `<td>${esc(b[k])}</td>`).join("") + "</tr>").join("");\n  return `<table><thead>${kepala}</thead><tbody>${isi}</tbody></table>`;\n}\n',
      ['tabelHTML([{ produk: "Kopi", qty: 2 }, { produk: "Teh", qty: 1 }])', "tabelHTML([])", 'tabelHTML([{ nama: "<b>x</b>" }])'],
      ["Ambil judul kolom dari Object.keys(baris[0]).", "Bangun string kepala dan isi terpisah dengan map + join, lalu gabungkan."],
      "Pola 'data → HTML' inilah yang dikerjakan framework (React, OWL di Odoo) secara otomatis dan aman.",
      cek={"tabelHTML([])": ""}),
  ])

# ---------------------------------------------------------------- 8. async
studi(id="js-async", topik="js", setelah="async", judul="async/await dan Promise.all", bahasa="js",
  contoh=dict(judul="Contoh: menunggu data",
    penjelasan="<p><code>await</code> menunggu Promise selesai di dalam fungsi <code>async</code>. <code>Promise.all</code> menjalankan beberapa permintaan bersamaan. Bungkus dengan <code>try/catch</code> untuk menangani kegagalan jaringan.</p>",
    kode='const tunda = (ms, nilai) => new Promise(r => setTimeout(() => r(nilai), ms));\nasync function utama() {\n  const a = await tunda(50, "data A");\n  const [b, c] = await Promise.all([tunda(50, "B"), tunda(50, "C")]);\n  console.log(a, b, c);\n  try { await Promise.reject(new Error("jaringan putus")); }\n  catch (e) { console.log("Ditangani:", e.message); }\n}\nawait utama();',
    kunci="Permintaan yang tidak saling bergantung → Promise.all (lebih cepat daripada await satu per satu)."),
  langkah=[
    J("js-async-1", "Total dari API", 1, "totalPesanan",
      "Buat <code>async function totalPesanan(ambil)</code>. <code>ambil()</code> mengembalikan Promise berisi array pesanan <code>{ total }</code>. Kembalikan jumlah semua total.",
      'async function totalPesanan(ambil) {\n  const pesanan = await ambil();\n  return pesanan.reduce((t, p) => t + p.total, 0);\n}\n',
      ["await totalPesanan(async () => [{ total: 100 }, { total: 250 }])", "await totalPesanan(async () => [])",
       "await totalPesanan(() => new Promise(r => setTimeout(() => r([{ total: 5 }]), 30)))"],
      ["const pesanan = await ambil();", "Lalu reduce seperti biasa."],
      "Tanpa await, pesanan berisi Promise, bukan array, dan reduce akan error.",
      awal="async function totalPesanan(ambil) {\n  // tulis kodemu di sini\n}\n",
      cek={"await totalPesanan(async () => [])": 0}),
    J("js-async-2", "Dashboard dengan cadangan", 2, "muatDashboard",
      "Buat <code>async function muatDashboard(ambilPenjualan, ambilStok)</code> yang menjalankan keduanya <b>bersamaan</b> dengan <code>Promise.all</code> dan mengembalikan <code>{ penjualan, stok, galat: null }</code>. Bila salah satu gagal, kembalikan <code>{ penjualan: [], stok: [], galat: pesanError }</code>.",
      'async function muatDashboard(ambilPenjualan, ambilStok) {\n  try {\n    const [penjualan, stok] = await Promise.all([ambilPenjualan(), ambilStok()]);\n    return { penjualan, stok, galat: null };\n  } catch (e) {\n    return { penjualan: [], stok: [], galat: e.message };\n  }\n}\n',
      ["await muatDashboard(async () => [1, 2], async () => [3])",
       'await muatDashboard(async () => [1], async () => { throw new Error("server stok mati"); })',
       "const mulai = Date.now();\nawait muatDashboard(() => new Promise(r => setTimeout(() => r([1]), 200)), () => new Promise(r => setTimeout(() => r([2]), 200)));\nconst hasil = Date.now() - mulai < 350;"],
      ["const [a, b] = await Promise.all([f(), g()]);", "Bungkus dengan try/catch; e.message berisi pesan error."],
      "Tes terakhir mengukur waktu: dua permintaan 200 ms harus selesai sekitar 200 ms (bersamaan), bukan 400 ms.",
      awal="async function muatDashboard(ambilPenjualan, ambilStok) {\n  // tulis kodemu di sini\n}\n",
      cek={'await muatDashboard(async () => [1], async () => { throw new Error("server stok mati"); })': {"penjualan": [], "stok": [], "galat": "server stok mati"}}),
  ])

# ---------------------------------------------------------------- 9. modern
studi(id="js-modern", topik="js", setelah="modern", judul="Optional chaining dan pengelompokan", bahasa="js",
  contoh=dict(judul="Contoh: ?. dan ??",
    penjelasan="<p><code>a?.b?.c</code> berhenti dengan <code>undefined</code> bila ada bagian yang kosong, tanpa error. Digabung dengan <code>??</code> untuk nilai bawaan. Method modern lain: <code>Object.entries</code>, <code>Array.from</code>, <code>includes</code>, <code>at(-1)</code>.</p>",
    kode='const user = { nama: "Ani", alamat: null };\nconsole.log(user.alamat?.kota ?? "Kota belum diisi");\nconsole.log([3, 5, 9].at(-1), ["a", "b"].includes("b"));\nconst kelompok = ["apel", "anggur", "mangga"].reduce((o, b) => ((o[b[0]] ??= []).push(b), o), {});\nconsole.log(kelompok);',
    kunci="?. untuk data API yang mungkin tidak lengkap. ??= mengisi hanya bila masih null/undefined."),
  langkah=[
    J("js-mod-1", "Kota pelanggan", 1, "kotaPelanggan",
      "Buat <code>kotaPelanggan(order)</code> yang mengembalikan <code>order.partner.alamat.kota</code>, atau <code>\"Tidak diketahui\"</code> bila bagian mana pun kosong. Jangan sampai error.",
      'const kotaPelanggan = order => order?.partner?.alamat?.kota ?? "Tidak diketahui";\n',
      ['kotaPelanggan({ partner: { alamat: { kota: "Batam" } } })', "kotaPelanggan({ partner: null })", "kotaPelanggan({})", "kotaPelanggan(undefined)", 'kotaPelanggan({ partner: { alamat: { kota: "" } } })'],
      ["Rangkai ?. di setiap titik.", "Kota berupa string kosong tetap dikembalikan apa adanya (?? tidak mengganti \"\")."],
      "Data dari API Odoo (misalnya partner_id bernilai false) sering tidak lengkap; ?. mencegah aplikasi berhenti karena error.",
      awal="const kotaPelanggan = order => {\n  // tulis kodemu di sini\n};\n",
      cek={'kotaPelanggan({ partner: { alamat: { kota: "" } } })': ""}),
    J("js-mod-2", "Kelompokkan berdasarkan kunci", 2, "kelompokkan",
      "Buat <code>kelompokkan(data, kunci)</code> yang mengembalikan objek <code>{ nilaiKunci: [item, ...] }</code>. Item yang kuncinya kosong (null/undefined) masuk kelompok <code>\"(kosong)\"</code>.",
      'function kelompokkan(data, kunci) {\n  const hasil = {};\n  for (const item of data) {\n    const k = item[kunci] ?? "(kosong)";\n    (hasil[k] ??= []).push(item);\n  }\n  return hasil;\n}\n',
      ['kelompokkan([{ tim: "A", n: 1 }, { tim: "B", n: 2 }, { tim: "A", n: 3 }], "tim")', 'kelompokkan([{ tim: null }, { x: 1 }], "tim")', 'kelompokkan([], "tim")'],
      ["Untuk setiap item, tentukan k = item[kunci] ?? \"(kosong)\".", "(hasil[k] ??= []).push(item) membuat array baru bila belum ada."],
      "Mengelompokkan data adalah langkah pertama hampir semua laporan; di Odoo ini setara group by di list view.",
      cek={'kelompokkan([], "tim")': {}}),
  ])

# ---------------------------------------------------------------- 10. kasus (debugging)
studi(id="js-kasus", topik="js", setelah="kasus", judul="Debugging jebakan JavaScript", bahasa="js",
  contoh=dict(judul="Contoh: sort angka dan 0.1 + 0.2",
    penjelasan="<p>Dua jebakan terkenal: <code>sort()</code> tanpa pembanding mengurutkan angka sebagai teks (<code>[10, 9, 1]</code> → <code>[1, 10, 9]</code>), dan penjumlahan desimal tidak persis. Satu lagi: <code>==</code> mengubah tipe diam-diam.</p>",
    kode='console.log([10, 9, 1].sort());\nconsole.log([10, 9, 1].sort((a, b) => a - b));\nconsole.log(0.1 + 0.2, Math.round((0.1 + 0.2) * 100) / 100);\nconsole.log("" == 0, "" === 0);',
    kunci="Angka: sort((a, b) => a - b). Uang: bulatkan, atau hitung dalam satuan terkecil (sen) sebagai bilangan bulat."),
  langkah=[
    J("js-kasus-1", "Perbaiki peringkat nilai", 2, "peringkat",
      "Kode awal punya <b>dua bug</b>. <code>peringkat(nilai)</code> seharusnya mengembalikan 3 nilai tertinggi dari besar ke kecil, tanpa mengubah array asli.",
      'function peringkat(nilai) {\n  return [...nilai].sort((a, b) => b - a).slice(0, 3);\n}\n',
      ["peringkat([70, 100, 85, 9, 90])", "peringkat([5])", 'const n = [3, 1, 2];\nperingkat(n);\nconst hasil = n;', "peringkat([1000, 200, 30])"],
      ["Bug 1: sort tanpa pembanding mengurutkan sebagai teks ('100' < '70').", "Bug 2: sort mengubah array asli; salin dulu dengan [...nilai]."],
      "Dua bug ini sering lolos uji karena data contoh kebetulan berdigit sama.",
      awal='function peringkat(nilai) {\n  return nilai.sort().reverse().slice(0, 3);\n}\n',
      cek={"peringkat([1000, 200, 30])": [1000, 200, 30]}),
    J("js-kasus-2", "Perbaiki total keranjang", 2, "totalKeranjang",
      "Kode awal punya <b>tiga bug</b>. <code>totalKeranjang(items)</code> menerima item <code>{ harga, qty }</code> di mana <code>qty</code> bisa berupa string dari input form (\"2\"). Kembalikan total dibulatkan 2 desimal (number). Item dengan qty kosong/tidak valid dilewati.",
      'function totalKeranjang(items) {\n  let total = 0;\n  for (const item of items) {\n    const qty = Number(item.qty);\n    if (!Number.isFinite(qty) || item.qty === "") continue;\n    total += item.harga * qty;\n  }\n  return Math.round(total * 100) / 100;\n}\n',
      ['totalKeranjang([{ harga: 0.1, qty: "1" }, { harga: 0.2, qty: 1 }])', 'totalKeranjang([{ harga: 15000, qty: "2" }, { harga: 6000, qty: "abc" }])', "totalKeranjang([])", 'totalKeranjang([{ harga: 10, qty: "" }, { harga: 5, qty: 3 }])'],
      ["Bug 1: var + for...in di array. Bug 2: qty string dijumlahkan. Bug 3: 0.1 + 0.2.", "Number(\"abc\") = NaN; cek dengan Number.isFinite. Number(\"\") = 0, jadi string kosong perlu dicek terpisah."],
      "Input form selalu string. Lupa mengubahnya ke angka membuat 15000 * \"2\" kebetulan benar tetapi \"2\" + 1 menjadi \"21\".",
      awal='function totalKeranjang(items) {\n  var total = 0;\n  for (var i in items) {\n    total = total + items[i].harga * items[i].qty;\n  }\n  return total;\n}\n',
      cek={'totalKeranjang([{ harga: 0.1, qty: "1" }, { harga: 0.2, qty: 1 }])': 0.3}),
  ])

# ---------------------------------------------------------------- 11. scope & closure
studi(id="js-scope", topik="js", setelah="scope", judul="Closure: fungsi yang mengingat", bahasa="js",
  contoh=dict(judul="Contoh: penghitung privat",
    penjelasan="<p>Closure terjadi ketika fungsi dalam tetap bisa memakai variabel fungsi luar walau fungsi luar sudah selesai. Ini cara membuat data 'privat' tanpa class.</p>",
    kode='function buatPenghitung() {\n  let n = 0;\n  return { tambah: () => ++n, nilai: () => n };\n}\nconst a = buatPenghitung(), b = buatPenghitung();\na.tambah(); a.tambah(); b.tambah();\nconsole.log(a.nilai(), b.nilai());',
    kunci="Setiap pemanggilan buatPenghitung() membuat variabel n sendiri."),
  langkah=[
    J("js-scope-1", "Nomor antrean", 1, "buatAntrean",
      "Buat <code>buatAntrean(awalan)</code> yang mengembalikan fungsi. Setiap dipanggil, fungsi itu mengembalikan nomor berikutnya: <code>\"A001\"</code>, <code>\"A002\"</code>, … (3 digit). Setiap antrean punya penghitung sendiri.",
      'function buatAntrean(awalan) {\n  let n = 0;\n  return () => awalan + String(++n).padStart(3, "0");\n}\n',
      ['const a = buatAntrean("A");\na();\nconst hasil = a();', 'const a = buatAntrean("A"), b = buatAntrean("B");\na(); a();\nconst hasil = [a(), b()];', 'buatAntrean("CS-")()'],
      ["Simpan let n = 0 di fungsi luar, kembalikan fungsi yang menaikkan n.", "padStart(3, \"0\") menambah nol di depan."],
      "Closure menjaga n tetap ada di antara pemanggilan tanpa variabel global.",
      cek={'buatAntrean("CS-")()': "CS-001"}),
    J("js-scope-2", "Fungsi sekali jalan dan memo", 2, "memo",
      "Buat <code>memo(fn)</code> yang mengembalikan fungsi baru: hasil untuk argumen yang sama disimpan, sehingga <code>fn</code> hanya dipanggil sekali per argumen. Fungsi hasil juga punya properti <code>panggilan</code> yang mencatat berapa kali <code>fn</code> benar-benar dipanggil.",
      'function memo(fn) {\n  const cache = new Map();\n  const bungkus = x => {\n    if (!cache.has(x)) {\n      cache.set(x, fn(x));\n      bungkus.panggilan++;\n    }\n    return cache.get(x);\n  };\n  bungkus.panggilan = 0;\n  return bungkus;\n}\n',
      ['const kuadrat = memo(x => x * x);\nkuadrat(4); kuadrat(4); kuadrat(5);\nconst hasil = [kuadrat(5), kuadrat.panggilan];', 'const f = memo(x => x + 1);\nconst hasil = f.panggilan;', 'const g = memo(s => s.toUpperCase());\nconst hasil = [g("a"), g("a"), g("b"), g.panggilan];'],
      ["Simpan hasil di Map di dalam closure.", "Properti fungsi bisa ditambahkan langsung: bungkus.panggilan = 0."],
      "Memoization mempercepat perhitungan mahal yang sering diulang dengan argumen sama.",
      cek={'const f = memo(x => x + 1);\nconst hasil = f.panggilan;': 0}),
  ])

# ---------------------------------------------------------------- 12. event & form (logika tanpa DOM)
studi(id="js-event", topik="js", setelah="event", judul="Validasi form dan debounce", bahasa="js",
  contoh=dict(judul="Contoh: logika validasi terpisah dari DOM",
    penjelasan="<p>Logika validasi sebaiknya fungsi murni (data masuk → pesan error keluar) yang dipanggil dari event <code>submit</code>. Debounce menunda pemanggilan sampai pengguna berhenti mengetik, cocok untuk kotak pencarian.</p>",
    kode='function validasi({ email }) {\n  return /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email) ? {} : { email: "Format email salah" };\n}\nconsole.log(validasi({ email: "ani@x.id" }), validasi({ email: "ani" }));\n// form.addEventListener("submit", e => { const err = validasi(data); if (Object.keys(err).length) e.preventDefault(); });',
    kunci="Pisahkan logika (mudah dites) dari kode DOM (addEventListener)."),
  langkah=[
    J("js-ev-1", "Validasi form lamaran", 2, "validasiLamaran",
      "Buat <code>validasiLamaran(data)</code> yang mengembalikan objek error (kosong bila valid): <code>nama</code> wajib minimal 3 huruf setelah trim → <code>\"Nama minimal 3 huruf\"</code>; <code>email</code> harus mengandung <code>@</code> dan titik setelahnya → <code>\"Email tidak valid\"</code>; <code>umur</code> harus angka 17–60 → <code>\"Umur 17-60\"</code>.",
      'function validasiLamaran(data) {\n  const err = {};\n  if ((data.nama ?? "").trim().length < 3) err.nama = "Nama minimal 3 huruf";\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(data.email ?? "")) err.email = "Email tidak valid";\n  const umur = Number(data.umur);\n  if (!(umur >= 17 && umur <= 60)) err.umur = "Umur 17-60";\n  return err;\n}\n',
      ['validasiLamaran({ nama: "Jauza", email: "j@mail.com", umur: "22" })', 'validasiLamaran({ nama: " Al ", email: "j@mail", umur: 15 })', "validasiLamaran({})", 'validasiLamaran({ nama: "Budi", email: "b@x.id", umur: "abc" })'],
      ["Mulai dengan const err = {} lalu isi kunci yang salah.", "Pola email sederhana: /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/. Number(\"abc\") adalah NaN, dan perbandingan dengan NaN selalu false."],
      "Mengembalikan objek per field memudahkan menampilkan pesan di bawah input yang tepat.",
      cek={'validasiLamaran({ nama: "Jauza", email: "j@mail.com", umur: "22" })': {}}),
    J("js-ev-2", "Debounce pencarian", 3, "debounce",
      "Buat <code>debounce(fn, ms)</code>: fungsi hasil menunda pemanggilan <code>fn</code> sampai tidak ada panggilan baru selama <code>ms</code> milidetik, lalu memanggil <code>fn</code> dengan argumen <b>terakhir</b>.",
      'function debounce(fn, ms) {\n  let timer;\n  return (...args) => {\n    clearTimeout(timer);\n    timer = setTimeout(() => fn(...args), ms);\n  };\n}\n',
      ['const log = [];\nconst cari = debounce(q => log.push(q), 50);\ncari("o"); cari("od"); cari("odoo");\nawait new Promise(r => setTimeout(r, 120));\nconst hasil = log;',
       'const log = [];\nconst f = debounce(x => log.push(x), 30);\nf(1);\nawait new Promise(r => setTimeout(r, 80));\nf(2);\nawait new Promise(r => setTimeout(r, 80));\nconst hasil = log;',
       'const log = [];\nconst f = debounce(x => log.push(x), 50);\nf(1);\nconst hasil = log.length;'],
      ["Simpan id timer di closure; setiap panggilan clearTimeout lalu setTimeout lagi.", "Rest/spread: (...args) => fn(...args) meneruskan semua argumen."],
      "Tanpa debounce, mengetik 'odoo' mengirim 4 permintaan pencarian; dengan debounce hanya 1.",
      cek={'const log = [];\nconst f = debounce(x => log.push(x), 50);\nf(1);\nconst hasil = log.length;': 0}),
  ])

# ---------------------------------------------------------------- 13. kelas
studi(id="js-kelas", topik="js", setelah="kelas", judul="Class, field privat, dan extends", bahasa="js",
  contoh=dict(judul="Contoh: #privat, getter, extends",
    penjelasan="<p><code>#saldo</code> adalah field privat: tidak bisa dibaca dari luar class. <code>get saldo()</code> membuat properti baca-saja. <code>class B extends A</code> mewarisi; panggil <code>super(...)</code> di constructor.</p>",
    kode='class Akun {\n  #saldo = 0;\n  constructor(nama) { this.nama = nama; }\n  setor(n) { this.#saldo += n; return this; }\n  get saldo() { return this.#saldo; }\n}\nclass AkunPremium extends Akun {\n  constructor(nama) { super(nama); this.level = "premium"; }\n}\nconst a = new AkunPremium("Ani").setor(100).setor(50);\nconsole.log(a.nama, a.level, a.saldo, a.saldoX);',
    kunci="return this memungkinkan pemanggilan berantai: a.setor(1).setor(2)."),
  langkah=[
    J("js-kelas-1", "Class Keranjang", 2, "Keranjang",
      "Buat class <code>Keranjang</code> dengan field privat <code>#isi</code> (Map). Method <code>tambah(nama, harga, qty = 1)</code> (nama sama menambah qty, mengembalikan <code>this</code>), <code>hapus(nama)</code>, getter <code>total</code>, dan getter <code>jumlahBarang</code> (total qty).",
      'class Keranjang {\n  #isi = new Map();\n  tambah(nama, harga, qty = 1) {\n    const lama = this.#isi.get(nama);\n    this.#isi.set(nama, { harga, qty: (lama?.qty ?? 0) + qty });\n    return this;\n  }\n  hapus(nama) {\n    this.#isi.delete(nama);\n    return this;\n  }\n  get total() {\n    let t = 0;\n    for (const { harga, qty } of this.#isi.values()) t += harga * qty;\n    return t;\n  }\n  get jumlahBarang() {\n    let n = 0;\n    for (const { qty } of this.#isi.values()) n += qty;\n    return n;\n  }\n}\n',
      ['const k = new Keranjang().tambah("Kopi", 18000, 2).tambah("Roti", 15000);\nconst hasil = [k.total, k.jumlahBarang];', 'const k = new Keranjang().tambah("Kopi", 18000).tambah("Kopi", 18000, 2);\nconst hasil = k.jumlahBarang;', 'const k = new Keranjang().tambah("A", 10).hapus("A").hapus("B");\nconst hasil = [k.total, k.jumlahBarang];', 'const k = new Keranjang();\nconst hasil = [k.isi === undefined, Object.keys(k).length];'],
      ["#isi = new Map() sebagai field privat; get/set/delete untuk mengubahnya.", "Getter ditulis get total() { ... } dan dipakai tanpa kurung: k.total."],
      "Tes terakhir memastikan isi keranjang tidak bisa diakses langsung dari luar (k.isi bernilai undefined).",
      awal="class Keranjang {\n  // tulis kodemu di sini\n}\n",
      cek={'const k = new Keranjang().tambah("Kopi", 18000).tambah("Kopi", 18000, 2);\nconst hasil = k.jumlahBarang;': 3}),
    J("js-kelas-2", "Pewarisan: Karyawan dan Manajer", 2, "Manajer",
      "Class <code>Karyawan</code> sudah ada. Buat <code>Manajer extends Karyawan</code> dengan tambahan <code>tim</code> (array nama). Override <code>gaji()</code>: gaji induk + 500.000 per anggota tim, dan <code>toString()</code>: teks induk + <code>\" (tim: N)\"</code>.",
      'class Karyawan {\n  constructor(nama, pokok) { this.nama = nama; this.pokok = pokok; }\n  gaji() { return this.pokok; }\n  toString() { return `${this.nama}: ${this.gaji()}`; }\n}\n\nclass Manajer extends Karyawan {\n  constructor(nama, pokok, tim = []) {\n    super(nama, pokok);\n    this.tim = tim;\n  }\n  gaji() { return super.gaji() + 500000 * this.tim.length; }\n  toString() { return `${super.toString()} (tim: ${this.tim.length})`; }\n}\n',
      ['new Manajer("Rina", 8000000, ["Ani", "Budi"]).gaji()', 'String(new Manajer("Rina", 8000000, ["Ani", "Budi"]))', 'String(new Manajer("Sari", 7000000))', 'new Manajer("X", 1) instanceof Karyawan'],
      ["constructor anak wajib memanggil super(nama, pokok) sebelum memakai this.", "super.gaji() dan super.toString() memanggil versi induk."],
      "Polanya sama dengan _inherit + super() di Odoo, hanya sintaksnya JavaScript.",
      awal='class Karyawan {\n  constructor(nama, pokok) { this.nama = nama; this.pokok = pokok; }\n  gaji() { return this.pokok; }\n  toString() { return `${this.nama}: ${this.gaji()}`; }\n}\n\nclass Manajer extends Karyawan {\n  // tulis kodemu di sini\n}\n',
      cek={'String(new Manajer("Rina", 8000000, ["Ani", "Budi"]))': "Rina: 9000000 (tim: 2)"}),
  ])

# ---------------------------------------------------------------- 14. error
studi(id="js-error", topik="js", setelah="error", judul="throw, try/catch, dan error buatan sendiri", bahasa="js",
  contoh=dict(judul="Contoh: class error sendiri",
    penjelasan="<p>Lempar error dengan <code>throw new Error(\"pesan\")</code>. Class turunan <code>Error</code> membuat jenis error bisa dibedakan di <code>catch</code> dengan <code>instanceof</code>. <code>finally</code> selalu dijalankan.</p>",
    kode='class ValidasiError extends Error {\n  constructor(field, pesan) { super(pesan); this.name = "ValidasiError"; this.field = field; }\n}\ntry {\n  throw new ValidasiError("email", "Email wajib diisi");\n} catch (e) {\n  console.log(e instanceof ValidasiError, e.name, e.field, e.message);\n} finally {\n  console.log("selesai");\n}',
    kunci="Set this.name di class error agar nama jenisnya tampil benar di log."),
  langkah=[
    J("js-err-1", "Parse angka dengan error yang jelas", 1, "parseQty",
      "Buat class <code>ValidasiError extends Error</code> (name <code>\"ValidasiError\"</code>) dan fungsi <code>parseQty(teks)</code> yang mengembalikan bilangan bulat positif dari teks. Lempar <code>ValidasiError</code> dengan pesan <code>\"qty harus bilangan bulat positif\"</code> bila tidak valid.",
      'class ValidasiError extends Error {\n  constructor(pesan) {\n    super(pesan);\n    this.name = "ValidasiError";\n  }\n}\n\nfunction parseQty(teks) {\n  const n = Number(String(teks).trim());\n  if (!Number.isInteger(n) || n <= 0) throw new ValidasiError("qty harus bilangan bulat positif");\n  return n;\n}\n',
      ['parseQty(" 12 ")', 'let hasil;\ntry { parseQty("2.5"); hasil = "tidak error"; } catch (e) { hasil = [e.name, e.message, e instanceof ValidasiError, e instanceof Error]; }', 'let hasil;\ntry { parseQty("0"); } catch (e) { hasil = e.name; }', 'let hasil;\ntry { parseQty("abc"); } catch (e) { hasil = e.name; }'],
      ["class ValidasiError extends Error { constructor(pesan) { super(pesan); this.name = \"ValidasiError\"; } }", "Number.isInteger memeriksa bilangan bulat; tambahkan syarat > 0."],
      "Error dengan jenis sendiri membuat penanganan lebih tepat: error validasi ditampilkan ke pengguna, error lain dicatat ke log.",
      awal="class ValidasiError extends Error {\n  // lengkapi\n}\n\nfunction parseQty(teks) {\n  // tulis kodemu di sini\n}\n",
      cek={'parseQty(" 12 ")': 12}),
    J("js-err-2", "Jalankan dengan aman", 2, "coba",
      "Buat <code>async function coba(fn, cadangan)</code> yang mengembalikan <code>{ ok: true, nilai }</code> bila <code>fn()</code> (boleh async) berhasil, atau <code>{ ok: false, nilai: cadangan, galat: pesan }</code> bila gagal. Fungsi <code>coba</code> juga mencatat <code>coba.jumlah</code>: berapa kali ia dipanggil (bertambah di blok <code>finally</code>).",
      'async function coba(fn, cadangan) {\n  try {\n    return { ok: true, nilai: await fn() };\n  } catch (e) {\n    return { ok: false, nilai: cadangan, galat: e.message };\n  } finally {\n    coba.jumlah = (coba.jumlah ?? 0) + 1;\n  }\n}\n',
      ["await coba(() => 42, 0)", 'await coba(async () => { throw new Error("timeout"); }, [])', 'await coba(() => 1);\nawait coba(() => { throw new Error("x"); });\nconst hasil = coba.jumlah;'],
      ["await fn() bekerja untuk fungsi biasa maupun async.", "finally dijalankan baik setelah return di try maupun di catch."],
      "Pembungkus seperti ini dipakai robot RPA agar satu langkah yang gagal tidak menghentikan seluruh proses.",
      awal="async function coba(fn, cadangan) {\n  // tulis kodemu di sini\n}\n",
      cek={"await coba(() => 42, 0)": {"ok": True, "nilai": 42}}),
  ])

# ---------------------------------------------------------------- 15. koleksi
studi(id="js-koleksi", topik="js", setelah="koleksi", judul="Map, Set, Date, dan regex", bahasa="js",
  contoh=dict(judul="Contoh: Set untuk unik, Map untuk hitung",
    penjelasan="<p><code>new Set(arr)</code> membuang duplikat. <code>Map</code> menyimpan pasangan kunci-nilai dengan kunci tipe apa pun dan urutan terjaga. <code>Object.fromEntries(map)</code> mengubah Map menjadi objek biasa.</p>",
    kode='const kata = "odoo itu odoo".split(" ");\nconsole.log([...new Set(kata)]);\nconst hitung = new Map();\nfor (const k of kata) hitung.set(k, (hitung.get(k) ?? 0) + 1);\nconsole.log(Object.fromEntries(hitung));\nconsole.log("INV/2026/0042".match(/\\d+/g));\nconsole.log(new Date("2026-11-24T00:00:00Z").getUTCDay());',
    kunci="Set → unik. Map → hitung/kelompok. Regex dengan flag g → semua kecocokan."),
  langkah=[
    J("js-kol-1", "Kata terbanyak", 1, "kataTerbanyak",
      "Buat <code>kataTerbanyak(teks, n)</code>: ubah ke huruf kecil, ambil kata (huruf/angka saja, pakai regex), hitung dengan <code>Map</code>, lalu kembalikan <code>n</code> pasangan <code>[kata, jumlah]</code> terbanyak; seri diurutkan abjad.",
      'function kataTerbanyak(teks, n) {\n  const hitung = new Map();\n  for (const k of teks.toLowerCase().match(/[a-z0-9]+/g) ?? []) hitung.set(k, (hitung.get(k) ?? 0) + 1);\n  return [...hitung].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, n);\n}\n',
      ['kataTerbanyak("Odoo itu mudah. Odoo itu seru, seru!", 2)', 'kataTerbanyak("", 3)', 'kataTerbanyak("b a b a c", 5)'],
      ["teks.toLowerCase().match(/[a-z0-9]+/g) memberi array kata, atau null bila tidak ada (pakai ?? []).", "[...map] mengubah Map menjadi array pasangan, siap diurutkan."],
      "match dengan flag g mengembalikan null bila tidak ada yang cocok, bukan array kosong. Itu sebabnya ?? [] diperlukan.",
      cek={'kataTerbanyak("", 3)': []}),
    J("js-kol-2", "Format tanggal dan jatuh tempo", 2, "jatuhTempo",
      "Buat <code>jatuhTempo(tanggalISO, hari)</code> yang menambah <code>hari</code> ke tanggal <code>\"YYYY-MM-DD\"</code> dan mengembalikan format Indonesia <code>\"DD/MM/YYYY\"</code>. Hitung dalam UTC agar tidak terpengaruh zona waktu.",
      'function jatuhTempo(tanggalISO, hari) {\n  const d = new Date(tanggalISO + "T00:00:00Z");\n  d.setUTCDate(d.getUTCDate() + hari);\n  const dua = n => String(n).padStart(2, "0");\n  return `${dua(d.getUTCDate())}/${dua(d.getUTCMonth() + 1)}/${d.getUTCFullYear()}`;\n}\n',
      ['jatuhTempo("2026-11-24", 30)', 'jatuhTempo("2028-02-28", 1)', 'jatuhTempo("2026-12-31", 1)', 'jatuhTempo("2026-01-31", 0)'],
      ["new Date(\"2026-11-24T00:00:00Z\") membuat tanggal UTC; setUTCDate menambah hari dengan benar melewati akhir bulan.", "getUTCMonth() mulai dari 0, jadi tambah 1."],
      "Bulan di objek Date dimulai dari 0 (Januari = 0): sumber bug klasik. Memakai UTC mencegah tanggal bergeser sehari karena zona waktu.",
      cek={'jatuhTempo("2028-02-28", 1)': "29/02/2028"}),
  ])

# ---------------------------------------------------------------- 16. modul & JSON
studi(id="js-modul", topik="js", setelah="modul", judul="JSON dan konfigurasi", bahasa="js",
  contoh=dict(judul="Contoh: JSON.parse dengan nilai bawaan",
    penjelasan="<p><code>JSON.parse</code> mengubah teks JSON menjadi objek; teks rusak melempar <code>SyntaxError</code>. <code>JSON.stringify(obj, null, 2)</code> menulis JSON rapi. File <code>package.json</code> di proyek Node juga JSON biasa.</p>",
    kode='const bawaan = { tema: "terang", bahasa: "id" };\nfunction bacaKonfig(teks) {\n  try { return { ...bawaan, ...JSON.parse(teks) }; }\n  catch { return bawaan; }\n}\nconsole.log(bacaKonfig(\'{"tema":"gelap"}\'), bacaKonfig("rusak"));\nconsole.log(JSON.stringify({ a: 1, b: [2, 3] }, null, 2));',
    kunci="Selalu bungkus JSON.parse dengan try/catch bila teksnya datang dari luar."),
  langkah=[
    J("js-modul-1", "Baca konfigurasi", 1, "bacaKonfig",
      "Buat <code>bacaKonfig(teks)</code> yang menggabungkan nilai bawaan <code>{ tema: \"terang\", bahasa: \"id\", ukuran: 16 }</code> dengan isi JSON. Bila JSON rusak atau bukan objek (misalnya array atau angka), kembalikan bawaan saja.",
      'const BAWAAN = { tema: "terang", bahasa: "id", ukuran: 16 };\n\nfunction bacaKonfig(teks) {\n  try {\n    const isi = JSON.parse(teks);\n    if (!isi || typeof isi !== "object" || Array.isArray(isi)) return { ...BAWAAN };\n    return { ...BAWAAN, ...isi };\n  } catch {\n    return { ...BAWAAN };\n  }\n}\n',
      ['bacaKonfig(\'{"tema": "gelap"}\')', 'bacaKonfig("{rusak")', 'bacaKonfig("[1, 2]")', 'bacaKonfig("42")', 'bacaKonfig(\'{"ukuran": 18, "baru": true}\')'],
      ["try { JSON.parse(...) } catch { ... }", "Cek bentuknya: objek biasa, bukan array, bukan null."],
      "JSON yang valid belum tentu berbentuk sesuai harapan. Memeriksa bentuk data adalah validasi di batas sistem.",
      cek={'bacaKonfig("[1, 2]")': {"tema": "terang", "bahasa": "id", "ukuran": 16}}),
    J("js-modul-2", "Ringkas package.json", 2, "ringkasPackage",
      "Buat <code>ringkasPackage(teks)</code> yang membaca isi <code>package.json</code> dan mengembalikan <code>{ nama, versi, jumlahDependensi, scripts }</code>: jumlah dependencies + devDependencies, dan <code>scripts</code> berupa array nama script terurut. Kunci yang tidak ada dianggap kosong.",
      'function ringkasPackage(teks) {\n  const p = JSON.parse(teks);\n  return {\n    nama: p.name ?? "",\n    versi: p.version ?? "0.0.0",\n    jumlahDependensi: Object.keys(p.dependencies ?? {}).length + Object.keys(p.devDependencies ?? {}).length,\n    scripts: Object.keys(p.scripts ?? {}).sort(),\n  };\n}\n',
      ['ringkasPackage(\'{"name": "kodequiz", "version": "5.0.0", "dependencies": {"pyodide": "0.26.4"}, "devDependencies": {"eslint": "9", "playwright": "1"}, "scripts": {"test": "x", "build": "y"}}\')', 'ringkasPackage("{}")', 'ringkasPackage(\'{"name": "a", "scripts": {}}\')'],
      ["Object.keys(obj ?? {}).length menghitung kunci dengan aman.", "Pakai ?? untuk nilai bawaan nama dan versi."],
      "Membaca file konfigurasi seperti ini adalah tugas umum di alat otomasi dan skrip build.",
      cek={'ringkasPackage("{}")': {"nama": "", "versi": "0.0.0", "jumlahDependensi": 0, "scripts": []}}),
  ])

# ---------------------------------------------------------------- 17. frontend (gaya React)
studi(id="js-frontend", topik="js", setelah="frontend", judul="Reducer gaya React", bahasa="js",
  contoh=dict(judul="Contoh: state baru, bukan state yang diubah",
    penjelasan="<p>Di React (dan OWL di Odoo), tampilan dihitung dari <i>state</i>. State tidak diubah langsung; reducer menerima state lama + aksi, lalu mengembalikan state <b>baru</b>.</p>",
    kode='function reducer(state, aksi) {\n  switch (aksi.type) {\n    case "tambah": return { ...state, angka: state.angka + 1 };\n    case "reset": return { ...state, angka: 0 };\n    default: return state;\n  }\n}\nlet s = { angka: 0 };\ns = reducer(s, { type: "tambah" });\ns = reducer(s, { type: "tambah" });\nconsole.log(s, reducer(s, { type: "lain" }) === s);',
    kunci="Aksi yang tidak dikenal mengembalikan state yang sama persis."),
  langkah=[
    J("js-fe-1", "Reducer todo", 2, "todoReducer",
      "Buat <code>todoReducer(state, aksi)</code>. State: array <code>{ id, teks, selesai }</code>. Aksi: <code>{ type: \"tambah\", id, teks }</code> (menambah di akhir, teks di-trim, abaikan bila teks kosong), <code>{ type: \"toggle\", id }</code>, <code>{ type: \"hapus\", id }</code>. Selalu kembalikan array baru; aksi lain mengembalikan state yang sama.",
      'function todoReducer(state, aksi) {\n  switch (aksi.type) {\n    case "tambah": {\n      const teks = aksi.teks.trim();\n      return teks ? [...state, { id: aksi.id, teks, selesai: false }] : state;\n    }\n    case "toggle":\n      return state.map(t => t.id === aksi.id ? { ...t, selesai: !t.selesai } : t);\n    case "hapus":\n      return state.filter(t => t.id !== aksi.id);\n    default:\n      return state;\n  }\n}\n',
      ['todoReducer([], { type: "tambah", id: 1, teks: " Belajar Odoo " })', 'todoReducer([{ id: 1, teks: "a", selesai: false }], { type: "toggle", id: 1 })',
       'const s = [{ id: 1, teks: "a", selesai: false }];\ntodoReducer(s, { type: "toggle", id: 1 });\nconst hasil = s[0].selesai;', 'todoReducer([{ id: 1, teks: "a", selesai: true }, { id: 2, teks: "b", selesai: false }], { type: "hapus", id: 1 })',
       'const s = [];\nconst hasil = [todoReducer(s, { type: "x" }) === s, todoReducer(s, { type: "tambah", id: 9, teks: "  " }).length];'],
      ["switch (aksi.type) dengan case untuk setiap aksi.", "toggle: map + spread { ...t, selesai: !t.selesai }; hapus: filter."],
      "Tes 3 memastikan state lama tidak berubah: dasar dari fitur undo dan deteksi perubahan di React.",
      cek={'const s = [{ id: 1, teks: "a", selesai: false }];\ntodoReducer(s, { type: "toggle", id: 1 });\nconst hasil = s[0].selesai;': False}),
    J("js-fe-2", "Data turunan untuk tampilan", 2, "tampilanTodo",
      "Buat <code>tampilanTodo(todos, filter)</code> dengan filter <code>\"semua\"</code>, <code>\"aktif\"</code>, atau <code>\"selesai\"</code>. Kembalikan <code>{ daftar: [teks...], sisa: jumlahBelumSelesai, persen: persenSelesai (bulat) }</code>. Todo kosong → persen 0.",
      'function tampilanTodo(todos, filter) {\n  const cocok = { semua: () => true, aktif: t => !t.selesai, selesai: t => t.selesai }[filter] ?? (() => true);\n  const selesai = todos.filter(t => t.selesai).length;\n  return {\n    daftar: todos.filter(cocok).map(t => t.teks),\n    sisa: todos.length - selesai,\n    persen: todos.length ? Math.round(selesai / todos.length * 100) : 0,\n  };\n}\n',
      ['tampilanTodo([{ teks: "a", selesai: true }, { teks: "b", selesai: false }, { teks: "c", selesai: false }], "aktif")', 'tampilanTodo([{ teks: "a", selesai: true }], "selesai")', 'tampilanTodo([], "semua")'],
      ["Petakan nama filter ke fungsi saring dengan objek.", "Hitung jumlah selesai sekali, lalu pakai untuk sisa dan persen."],
      "Data turunan dihitung dari state, tidak disimpan terpisah, sehingga tidak pernah tidak sinkron.",
      cek={'tampilanTodo([], "semua")': {"daftar": [], "sisa": 0, "persen": 0}}),
  ])

# ======================================================================== 🏁 JavaScript
ujian_js("uji-js-1", "array", "Keranjang toko online", "Bab 1–5: variabel, operator, kondisi & perulangan, fungsi, array",
  "Kamu membuat logika keranjang belanja toko online. Data produk: <code>{ id, nama, harga, stok }</code>.",
  [dict(judul="Tambah ke keranjang", fungsi="tambahKeKeranjang",
     soal="Buat <code>tambahKeKeranjang(keranjang, produk, qty)</code> yang mengembalikan keranjang <b>baru</b> (array <code>{ id, nama, harga, qty }</code>). Produk yang sudah ada ditambah qty-nya. qty total tidak boleh melebihi <code>produk.stok</code> (dibatasi ke stok). qty ≤ 0 tidak mengubah apa pun.",
     solusi='function tambahKeKeranjang(keranjang, produk, qty) {\n  if (qty <= 0) return keranjang;\n  const ada = keranjang.find(i => i.id === produk.id);\n  const baru = Math.min(produk.stok, (ada ? ada.qty : 0) + qty);\n  if (ada) return keranjang.map(i => i.id === produk.id ? { ...i, qty: baru } : i);\n  return [...keranjang, { id: produk.id, nama: produk.nama, harga: produk.harga, qty: baru }];\n}\n',
     awal='function tambahKeKeranjang(keranjang, produk, qty) {\n  // tulis kodemu di sini\n}\n',
     tes=['tambahKeKeranjang([], { id: 1, nama: "Kopi", harga: 18000, stok: 5 }, 2)',
          'tambahKeKeranjang([{ id: 1, nama: "Kopi", harga: 18000, qty: 2 }], { id: 1, nama: "Kopi", harga: 18000, stok: 5 }, 9)',
          'const k = [{ id: 1, nama: "Kopi", harga: 18000, qty: 1 }];\ntambahKeKeranjang(k, { id: 1, nama: "Kopi", harga: 18000, stok: 5 }, 1);\nconst hasil = k[0].qty;',
          'tambahKeKeranjang([], { id: 2, nama: "Teh", harga: 6000, stok: 3 }, 0)'],
     petunjuk=["find mencari item yang sama; Math.min membatasi ke stok.", "Jangan ubah array lama: pakai map + spread atau [...keranjang, itemBaru]."],
     jelas="Keranjang yang immutable aman dipakai sebagai state aplikasi.",
     cek={'tambahKeKeranjang([], { id: 2, nama: "Teh", harga: 6000, stok: 3 }, 0)': []}),
   dict(judul="Hitung total", fungsi="hitungTotal",
     soal="Buat <code>hitungTotal(keranjang, kodeVoucher)</code> yang mengembalikan <code>{ subtotal, diskon, ongkir, total }</code>. Voucher <code>\"HEMAT10\"</code> = diskon 10% (maks 50.000), <code>\"GRATISONGKIR\"</code> = ongkir 0, lainnya tidak berlaku. Ongkir 15.000, tetapi gratis bila subtotal ≥ 200.000. Keranjang kosong: semua 0. Semua dibulatkan Math.round.",
     solusi='function hitungTotal(keranjang, kodeVoucher) {\n  const subtotal = keranjang.reduce((t, i) => t + i.harga * i.qty, 0);\n  if (subtotal === 0) return { subtotal: 0, diskon: 0, ongkir: 0, total: 0 };\n  const diskon = kodeVoucher === "HEMAT10" ? Math.min(50000, Math.round(subtotal * 0.1)) : 0;\n  const ongkir = kodeVoucher === "GRATISONGKIR" || subtotal >= 200000 ? 0 : 15000;\n  return { subtotal, diskon, ongkir, total: subtotal - diskon + ongkir };\n}\n',
     awal='function hitungTotal(keranjang, kodeVoucher) {\n  // tulis kodemu di sini\n}\n',
     tes=['hitungTotal([{ harga: 18000, qty: 2 }], "")', 'hitungTotal([{ harga: 18000, qty: 2 }], "HEMAT10")', 'hitungTotal([{ harga: 1000000, qty: 1 }], "HEMAT10")', 'hitungTotal([{ harga: 50000, qty: 2 }], "GRATISONGKIR")', 'hitungTotal([], "HEMAT10")', 'hitungTotal([{ harga: 100000, qty: 2 }], "SALAH")'],
     petunjuk=["Subtotal dengan reduce. Tangani keranjang kosong lebih dulu.", "Diskon: Math.min(50000, ...). Ongkir: ternary dengan dua syarat (||)."],
     jelas="Aturan bisnis seperti batas diskon dan ambang gratis ongkir paling sering salah di batasnya: uji tepat 200.000.",
     cek={'hitungTotal([{ harga: 100000, qty: 2 }], "SALAH")': {"subtotal": 200000, "diskon": 0, "ongkir": 0, "total": 200000}}),
   dict(judul="Ringkasan pesanan", fungsi="ringkasanPesanan",
     soal="Buat <code>ringkasanPesanan(keranjang, kodeVoucher)</code> yang memakai fungsi bagian B dan mengembalikan array baris teks: satu baris per item <code>\"2x Kopi - 36000\"</code> (urut nama), lalu <code>\"Diskon: 3600\"</code> (hanya bila &gt; 0), <code>\"Ongkir: 15000\"</code> atau <code>\"Ongkir: GRATIS\"</code>, dan <code>\"Total: 47400\"</code>. Keranjang kosong → <code>[\"Keranjang kosong\"]</code>.",
     solusi='function ringkasanPesanan(keranjang, kodeVoucher) {\n  if (!keranjang.length) return ["Keranjang kosong"];\n  const t = hitungTotal(keranjang, kodeVoucher);\n  const baris = [...keranjang].sort((a, b) => a.nama.localeCompare(b.nama)).map(i => `${i.qty}x ${i.nama} - ${i.harga * i.qty}`);\n  if (t.diskon > 0) baris.push(`Diskon: ${t.diskon}`);\n  baris.push(`Ongkir: ${t.ongkir ? t.ongkir : "GRATIS"}`);\n  baris.push(`Total: ${t.total}`);\n  return baris;\n}\n',
     awal='function ringkasanPesanan(keranjang, kodeVoucher) {\n  // tulis kodemu di sini\n}\n',
     tes=['ringkasanPesanan([{ nama: "Kopi", harga: 18000, qty: 2 }], "HEMAT10")', 'ringkasanPesanan([{ nama: "Teh", harga: 6000, qty: 1 }, { nama: "Roti", harga: 200000, qty: 1 }], "")', 'ringkasanPesanan([], "")'],
     petunjuk=["Panggil hitungTotal; jangan hitung ulang.", "Urutkan salinan keranjang berdasarkan nama dengan localeCompare."],
     jelas="Fungsi kecil yang sudah teruji (A, B) membuat fungsi akhir pendek dan mudah dibaca.",
     cek={'ringkasanPesanan([], "")': ["Keranjang kosong"]}),
  ])

ujian_js("uji-js-2", "kasus", "Data karyawan dari CSV", "Bab 6–10: string & objek, logika data tanpa DOM, async, JS modern, debugging",
  "HR mengirim data karyawan sebagai teks CSV. Kamu membangun pengolah datanya.",
  [dict(judul="Parse CSV", fungsi="parseKaryawan",
     soal="Buat <code>parseKaryawan(teks)</code>. Baris pertama header <code>nama,divisi,gaji,mulai</code>. Kembalikan array objek dengan <code>gaji</code> sebagai number dan <code>nama</code>/<code>divisi</code> di-trim. Baris kosong dilewati; baris yang gajinya bukan angka juga dilewati.",
     solusi='function parseKaryawan(teks) {\n  const [kepala, ...baris] = teks.trim().split("\\n");\n  const kunci = kepala.split(",").map(k => k.trim());\n  return baris\n    .filter(b => b.trim())\n    .map(b => Object.fromEntries(b.split(",").map((v, i) => [kunci[i], v.trim()])))\n    .map(o => ({ ...o, gaji: Number(o.gaji) }))\n    .filter(o => Number.isFinite(o.gaji) && o.gaji > 0);\n}\n',
     awal='function parseKaryawan(teks) {\n  // tulis kodemu di sini\n}\n',
     tes=['parseKaryawan("nama,divisi,gaji,mulai\\n Ani ,IT,8000000,2024-03-01\\nBudi,HR,abc,2023-01-10\\n\\nCita,IT,9500000,2022-07-15")', 'parseKaryawan("nama,divisi,gaji,mulai")', 'parseKaryawan("nama,divisi,gaji,mulai\\nDodi, Sales ,6000000,2025-01-02")'],
     petunjuk=["Destructuring: const [kepala, ...baris] = teks.trim().split(\"\\n\").", "Object.fromEntries(nilai.map((v, i) => [kunci[i], v.trim()])) membangun objek per baris."],
     jelas="Data dari file harus dibersihkan dan divalidasi sebelum diolah; baris rusak dilewati, bukan membuat program berhenti.",
     cek={'parseKaryawan("nama,divisi,gaji,mulai")': []}),
   dict(judul="Statistik per divisi", fungsi="statistikDivisi",
     soal="Buat <code>statistikDivisi(teks)</code> yang memakai bagian A dan mengembalikan objek <code>{ divisi: { jumlah, rataGaji, tertinggi } }</code>: rata-rata dibulatkan Math.round, <code>tertinggi</code> = nama karyawan bergaji tertinggi di divisi itu.",
     solusi='function statistikDivisi(teks) {\n  const hasil = {};\n  for (const k of parseKaryawan(teks)) {\n    const d = (hasil[k.divisi] ??= { jumlah: 0, total: 0, tertinggi: k.nama, max: -1 });\n    d.jumlah++;\n    d.total += k.gaji;\n    if (k.gaji > d.max) { d.max = k.gaji; d.tertinggi = k.nama; }\n  }\n  return Object.fromEntries(Object.entries(hasil).map(([div, d]) => [div, { jumlah: d.jumlah, rataGaji: Math.round(d.total / d.jumlah), tertinggi: d.tertinggi }]));\n}\n',
     awal='function statistikDivisi(teks) {\n  // tulis kodemu di sini\n}\n',
     tes=['statistikDivisi("nama,divisi,gaji,mulai\\nAni,IT,8000000,2024-03-01\\nBudi,HR,7000000,2023-01-10\\nCita,IT,9500000,2022-07-15\\nDodi,IT,7000001,2025-01-02")', 'statistikDivisi("nama,divisi,gaji,mulai")', 'statistikDivisi("nama,divisi,gaji,mulai\\nEka,QA,5000000,2026-01-05")'],
     petunjuk=["Kumpulkan dulu jumlah, total, dan gaji maksimum per divisi dengan ??=.", "Ubah ke bentuk akhir dengan Object.entries → map → Object.fromEntries."],
     jelas="Dua tahap (kumpulkan, lalu bentuk hasil) membuat kode agregasi mudah dibaca.",
     contoh=1,
     cek={'statistikDivisi("nama,divisi,gaji,mulai")': {}}),
   dict(judul="Laporan masa kerja", fungsi="laporanMasaKerja",
     soal="Buat <code>async function laporanMasaKerja(ambilTeks, hariIni)</code>: ambil teks CSV dengan <code>await ambilTeks()</code>, parse dengan bagian A, lalu kembalikan array <code>{ nama, tahun }</code> (tahun masa kerja penuh sampai <code>hariIni</code> \"YYYY-MM-DD\") diurutkan dari terlama; seri diurutkan nama. Bila <code>ambilTeks</code> gagal, kembalikan <code>[]</code>.",
     solusi='async function laporanMasaKerja(ambilTeks, hariIni) {\n  let teks;\n  try { teks = await ambilTeks(); } catch { return []; }\n  const [th, bl, hr] = hariIni.split("-").map(Number);\n  return parseKaryawan(teks)\n    .map(k => {\n      const [y, m, d] = k.mulai.split("-").map(Number);\n      const tahun = th - y - ((bl < m || (bl === m && hr < d)) ? 1 : 0);\n      return { nama: k.nama, tahun };\n    })\n    .sort((a, b) => b.tahun - a.tahun || a.nama.localeCompare(b.nama));\n}\n',
     awal='async function laporanMasaKerja(ambilTeks, hariIni) {\n  // tulis kodemu di sini\n}\n',
     tes=['await laporanMasaKerja(async () => "nama,divisi,gaji,mulai\\nAni,IT,8000000,2024-03-01\\nCita,IT,9500000,2022-11-25\\nBudi,HR,7000000,2022-11-24", "2026-11-24")',
          'await laporanMasaKerja(async () => { throw new Error("file tidak ada"); }, "2026-11-24")',
          'await laporanMasaKerja(async () => "nama,divisi,gaji,mulai", "2026-01-01")'],
     petunjuk=["Bungkus await ambilTeks() dengan try/catch.", "Tahun penuh: selisih tahun, dikurangi 1 bila (bulan, hari) ini belum mencapai (bulan, hari) mulai."],
     jelas="Cita yang mulai 25 November belum genap 4 tahun pada 24 November: batas tanggal seperti ini selalu diuji di soal HR.",
     cek={'await laporanMasaKerja(async () => { throw new Error("file tidak ada"); }, "2026-11-24")': []}),
  ])

ujian_js("uji-js-3", "koleksi", "Aplikasi catatan", "Bab 11–15: closure, validasi & debounce, class, error, Map/Set/Date/regex",
  "Kamu membuat inti aplikasi catatan: menyimpan catatan, mencari dengan tag, dan mengekspor.",
  [dict(judul="Class BukuCatatan", fungsi="BukuCatatan",
     soal="Buat class <code>BukuCatatan</code> dengan field privat <code>#data</code> (Map id → catatan) dan penghitung id mulai 1. Method <code>tambah(judul, isi)</code> mengembalikan id baru; judul kosong setelah trim melempar <code>Error(\"Judul wajib diisi\")</code>. Tag diambil otomatis dari isi: kata yang diawali <code>#</code> (huruf kecil, unik, urut abjad). Method <code>ambil(id)</code> mengembalikan salinan <code>{ id, judul, isi, tag }</code> atau <code>null</code>, dan getter <code>jumlah</code>.",
     solusi='class BukuCatatan {\n  #data = new Map();\n  #idBerikut = 1;\n  tambah(judul, isi) {\n    if (!judul.trim()) throw new Error("Judul wajib diisi");\n    const tag = [...new Set((isi.match(/#\\w+/g) ?? []).map(t => t.slice(1).toLowerCase()))].sort();\n    const id = this.#idBerikut++;\n    this.#data.set(id, { id, judul: judul.trim(), isi, tag });\n    return id;\n  }\n  ambil(id) {\n    const c = this.#data.get(id);\n    return c ? { ...c, tag: [...c.tag] } : null;\n  }\n  get jumlah() { return this.#data.size; }\n  semua() { return [...this.#data.values()].map(c => ({ ...c, tag: [...c.tag] })); }\n}\n',
     awal='class BukuCatatan {\n  // tulis kodemu di sini\n  // tambahkan juga method semua() yang mengembalikan salinan semua catatan (dipakai bagian B)\n}\n',
     tes=['const b = new BukuCatatan();\nconst id = b.tambah(" Rapat ", "Bahas #Odoo dan #rpa lalu #odoo lagi");\nconst hasil = [id, b.ambil(id), b.jumlah];',
          'const b = new BukuCatatan();\nb.tambah("a", "");\nconst hasil = [b.tambah("b", "x"), b.ambil(99)];',
          'const b = new BukuCatatan();\nlet hasil;\ntry { b.tambah("   ", "isi"); } catch (e) { hasil = [e.message, b.jumlah]; }',
          'const b = new BukuCatatan();\nconst id = b.tambah("a", "#x");\nb.ambil(id).tag.push("rusak");\nconst hasil = b.ambil(id).tag;'],
     petunjuk=["isi.match(/#\\w+/g) memberi semua tag (atau null). Buang tanda # dengan slice(1), unikkan dengan Set, lalu sort.", "ambil() mengembalikan SALINAN (spread + salin array tag) agar data di dalam tidak bisa dirusak dari luar."],
     jelas="Tes terakhir memastikan enkapsulasi: mengubah hasil ambil() tidak mengubah data asli.",
     cek={'const b = new BukuCatatan();\nb.tambah("a", "");\nconst hasil = [b.tambah("b", "x"), b.ambil(99)];': [2, None]}),
   dict(judul="Cari catatan", fungsi="cari",
     soal="Buat fungsi <code>cari(buku, kueri)</code>. Kueri berisi kata biasa dan/atau tag (<code>#odoo</code>). Catatan cocok bila mengandung <b>semua</b> tag di kueri dan <b>semua</b> kata biasa ada di judul atau isi (tanpa peduli huruf besar). Kembalikan array id terurut. Kueri kosong → semua id.",
     solusi='function cari(buku, kueri) {\n  const bagian = kueri.toLowerCase().split(/\\s+/).filter(Boolean);\n  const tag = bagian.filter(b => b.startsWith("#")).map(b => b.slice(1));\n  const kata = bagian.filter(b => !b.startsWith("#"));\n  return buku.semua()\n    .filter(c => tag.every(t => c.tag.includes(t)))\n    .filter(c => kata.every(k => (c.judul + " " + c.isi).toLowerCase().includes(k)))\n    .map(c => c.id)\n    .sort((a, b) => a - b);\n}\n',
     awal='function cari(buku, kueri) {\n  // tulis kodemu di sini\n}\n',
     tes=['const b = new BukuCatatan();\nb.tambah("Rapat Odoo", "modul #odoo #sales");\nb.tambah("Belanja", "kopi gula");\nb.tambah("Bug", "error di #odoo purchase");\nconst hasil = [cari(b, "#odoo"), cari(b, "#odoo purchase"), cari(b, "KOPI"), cari(b, ""), cari(b, "#rpa")];',
          'const hasil = cari(new BukuCatatan(), "apa saja");',
          'const b = new BukuCatatan();\nb.tambah("Ide", "Otomasi faktur #RPA");\nconst hasil = [cari(b, "#rpa"), cari(b, "faktur #rpa"), cari(b, "faktur #odoo")];'],
     petunjuk=["Pisahkan kueri menjadi tag (diawali #) dan kata biasa.", "every untuk syarat 'semua cocok'; includes untuk mengecek isi."],
     jelas="Pencarian dengan beberapa syarat AND adalah pola filter di hampir semua aplikasi, termasuk search view Odoo.",
     contoh=1,
     cek={'const b = new BukuCatatan();\nb.tambah("Rapat Odoo", "modul #odoo #sales");\nb.tambah("Belanja", "kopi gula");\nb.tambah("Bug", "error di #odoo purchase");\nconst hasil = [cari(b, "#odoo"), cari(b, "#odoo purchase"), cari(b, "KOPI"), cari(b, ""), cari(b, "#rpa")];': [[1, 3], [3], [2], [1, 2, 3], []]}),
   dict(judul="Statistik tag", fungsi="statistikTag",
     soal="Buat <code>statistikTag(buku)</code> yang mengembalikan array <code>[tag, jumlahCatatan]</code> memakai <code>Map</code>, diurutkan dari terbanyak; seri diurutkan abjad.",
     solusi='function statistikTag(buku) {\n  const hitung = new Map();\n  for (const c of buku.semua()) for (const t of c.tag) hitung.set(t, (hitung.get(t) ?? 0) + 1);\n  return [...hitung].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));\n}\n',
     awal='function statistikTag(buku) {\n  // tulis kodemu di sini\n}\n',
     tes=['const b = new BukuCatatan();\nb.tambah("1", "#odoo #sales");\nb.tambah("2", "#rpa");\nb.tambah("3", "#odoo #rpa #odoo");\nconst hasil = statistikTag(b);', 'const hasil = statistikTag(new BukuCatatan());', 'const b = new BukuCatatan();\nb.tambah("x", "#z #a");\nb.tambah("y", "#a");\nconst hasil = statistikTag(b);'],
     petunjuk=["Untuk setiap catatan dan setiap tagnya: hitung.set(t, (hitung.get(t) ?? 0) + 1).", "[...map] lalu sort dengan pemecah seri localeCompare."],
     jelas="Tag di catatan sudah unik (bagian A), jadi #odoo yang ditulis dua kali di satu catatan tetap dihitung sekali.",
     contoh=1,
     cek={'const hasil = statistikTag(new BukuCatatan());': []}),
  ])
